import React, { useState, useEffect, useRef, useMemo, useCallback, useReducer, createContext, useContext, Component } from 'react';

function App() {
  const [message, setMessage] = useState('');

  useEffect(() => {
    setMessage('Hello from React!');
  });

  return (
    <div>
      <h2 id="greeting">{message}</h2>
      <p id="status">Loaded successfully</p>
    </div>
  );
}

export default App;

