import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('The Infinite Loop', () => {
  test('Component renders without crashing', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#greeting');
if (!el) throw new Error('Component did not render — likely crashed');
  });

  test('Displays the greeting message', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#greeting');
if (!el.textContent.includes('Hello from React!'))
  throw new Error('Should display "Hello from React!"');
  });

  test('Shows "Loaded successfully"', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#status');
if (!el) throw new Error('No #status element');
if (!el.textContent.includes('Loaded successfully'))
  throw new Error('Should show "Loaded successfully"');
  });
});
